function summary=validate_hcp_stage3_behavior(workspace)
%VALIDATE_HCP_STAGE3_BEHAVIOR 只读LANGUAGE EPRIME；二选项/准确率代理奖励/真实RT工程验证。
if nargin<1,workspace=fileparts(fileparts(fileparts(mfilename('fullpath'))));end
addpath(fullfile(workspace,'function_toolkit'));setup_function;out=fullfile(workspace,'derivatives','function_stage3_behavior_20261017');if isfolder(out),error('cog:Exists','Preserve successful output');end;mkdir(out);subjects=["100206";"100307";"100408"];manifest=table;preparation=struct('records',{{}});
for s=1:3,for run=["LR","RL"]
    source=fullfile('D:/IBM',subjects(s)+"_extracted",subjects(s)+"_3T_tfMRI_LANGUAGE_unproc",subjects(s),'unprocessed','3T',"tfMRI_LANGUAGE_"+run,'LINKED_DATA','EPRIME');files=dir(fullfile(source,'*_TAB.txt'));if numel(files)~=1,error('cog:ExampleInput','Exactly one EPRIME table expected');end;file=fullfile(source,files(1).name);raw=cog.read_tsv(file,{'FilteredTrialStats.RESP','FilteredTrialStats.ACC','FilteredTrialStats.RTFromFirstOption','FilteredTrialStats.RTTIME','LeftResponseCode','RightResponseCode'});
    response=str2double(raw.('FilteredTrialStats.RESP'));reward=str2double(raw.('FilteredTrialStats.ACC'));rt=str2double(raw.('FilteredTrialStats.RTFromFirstOption'))/1000;responseTime=str2double(raw.('FilteredTrialStats.RTTIME'))/1000;left=unique(str2double(raw.LeftResponseCode));left=left(isfinite(left));right=unique(str2double(raw.RightResponseCode));right=right(isfinite(right));if numel(left)~=1||numel(right)~=1||left==right,error('cog:ExampleMapping','Unique explicit response-code map required');end
    good=ismember(response,[left right])&ismember(reward,[0 1])&isfinite(rt)&rt>0&rt<=30&isfinite(responseTime);rows=find(good);[~,order]=sort(responseTime(rows));rows=rows(order);choice=1+double(response(rows)==right);sync=readmatrix(fullfile(source,'EVs','Sync.txt'),'FileType','text');onset=responseTime(rows)-sync(1);published=[];for name={'response_story','response_math'},ev=readmatrix(fullfile(source,'EVs',[name{1} '.txt']),'FileType','text');published=[published;ev(:,1)];end %#ok<AGROW>
    errorSeconds=min(abs(onset-published'),[],2);timeVerified=all(errorSeconds<.02)&&all(onset>=0);
    trial_id="eprime_row_"+string(rows);block_id=repmat("run_reset",numel(rows),1);rewardSelected=reward(rows);rt_seconds=rt(rows);trials=table(trial_id,block_id,choice,rewardSelected,rt_seconds,'VariableNames',{'trial_id','block_id','choice','reward','rt_seconds'});if timeVerified,trials.onset_seconds=onset;end
    trialFile=fullfile(out,subjects(s)+"_"+run+"_trials.tsv");writetable(trials,trialFile,'FileType','text','Delimiter','\t');excluded=table(find(~good),repmat("missing/nonbinary response, missing accuracy, or invalid seconds RT",nnz(~good),1),'VariableNames',{'source_row','reason'});writetable(excluded,fullfile(out,subjects(s)+"_"+run+"_excluded.tsv"),'FileType','text','Delimiter','\t');manifest=[manifest;table(subjects(s),"","LANGUAGE_"+run,string(trialFile),'VariableNames',{'subject','session','run','trials_file'})];preparation.records{end+1}=struct('subject',subjects(s),'run',run,'source',file,'included',numel(rows),'excluded',nnz(~good),'leftCode',left,'rightCode',right,'minRtSeconds',min(rt(rows)),'maxRtSeconds',max(rt(rows)),'responseOnsetVerifiedAgainstEV',timeVerified,'maxNearestEvErrorSeconds',max(errorSeconds)); %#ok<AGROW>
end,end
file=fullfile(out,'runs.tsv');writetable(manifest,file,'FileType','text','Delimiter','\t');cog.write_json(fullfile(out,'PREPARATION.json'),preparation);c=behavior_config;c.manifestFile=file;c.execute=true;c.pythonExecutable='D:/matlab/atoolbox/function_glhmm_env/Scripts/python.exe';c.rw.nStarts=3;c.ddm.maxIterations=15;c.ddm.populationSize=6;
for method={'rw_softmax','ddm'},c.method=method{1};c.outputRoot=fullfile(out,method{1});summary.(method{1})=run_behavior(c);end
summary.scope='Three HCP subjects/two LANGUAGE runs: actual binary response codes and trial RT from first audio option, ACC used solely as an engineering reward proxy. RW reset each run; constant unbiased DDM pools question types, fixed noise1/mixture. Not a reinforcement-learning task or validated diffusion-decision epoch; no parameter/learning/neural interpretation or convergence claim. Raw EPRIME/EV untouched; onsets exported only if independently matching published response EVs.';cog.write_json(fullfile(out,'VALIDATION.json'),summary);
end
